"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["57619"],{16584(e){e.exports=JSON.parse('{"id":"F435","slug":"uncovered-interest-parity","name":"Uncovered Interest Parity and Unhedged Return","subject":"International Finance","section":"Global Finance","topic":"Interest rate parity (covered and uncovered)","level":"Intermediate","aliases":["UIP","interest rate parity","expected depreciation","forward premium puzzle"],"formula":{"latex":"E[S_{1}]=S_{0}\\\\,\\\\frac{1+r_{d}}{1+r_{f}},\\\\quad R_{unhedged}=(1+r_{f})\\\\frac{S_{1}}{S_{0}}-1","also":[],"text":"Uncovered parity: the expected future spot equals today\'s spot x (1 + domestic rate) / (1 + foreign rate), so the higher-rate currency is expected to weaken; Unhedged return in domestic currency = (1 + foreign rate) x (future spot / spot) - 1"},"symbols":[{"symbol":"S_0, S_1","meaning":"Spot rate today and at the end of the period (domestic per foreign)","unit":"rate"},{"symbol":"r_d, r_f","meaning":"Interest rates at home and abroad","unit":"per year"},{"symbol":"R_unhedged","meaning":"Return on a foreign deposit in domestic currency, with no hedge","unit":"percent"}],"when_to_use":"Use it as a benchmark for currency forecasts. If uncovered parity held, there would be no gain from holding a high-yield currency, because it would fall by the interest advantage. In the data, high-yield currencies have on average not fallen as much as parity says, which is why carry trades have earned a premium, with sharp losses in crises. The unhedged return shows what depends on the future spot.","worked_example":{"problem":"EUR/USD spot is 1.0850, the one-year USD rate is 5% and the EUR rate 3%. After a year the spot is 1.1200.","inputs":{"s0":1.085,"rd":5,"rf":3,"s1":1.12},"steps":[{"label":"Expected spot under parity","working":"1.085 x (1+0.05) / (1+0.03)","value":"1.1061"},{"label":"Expected change in the euro","working":"1.10607 / 1.085-1","value":"1.94%"},{"label":"Direction (1 = euro expected to rise, 0 = fall)","working":"1 if 0.0194175>0 else 0","value":"1"},{"label":"Unhedged return of the euro deposit in USD","working":"(1+0.03) x 1.12 / 1.085-1","value":"6.32%"},{"label":"Excess over the USD deposit","working":"0.0632258-0.05","value":"1.32%"}],"answer":"Parity implies an expected spot of 1.1061, so the euro would be expected to change by 1.94% (direction flag 1: 1 = rise, 0 = fall). If the spot actually reaches 1.1200 the unhedged euro deposit returns 6.32% in dollars, against 5% on the dollar deposit, a gain of 1.32% over the domestic deposit."},"calculator":{"available":true,"inputs":[{"id":"s0","label":"Spot today (USD per EUR)","unit":"","type":"number","default":1.085,"hint":""},{"id":"rd","label":"USD interest rate","unit":"%","type":"number","default":5,"hint":""},{"id":"rf","label":"EUR interest rate","unit":"%","type":"number","default":3,"hint":""},{"id":"s1","label":"Spot at the end of the year","unit":"","type":"number","default":1.12,"hint":""}],"checks":[{"expr":"s0>0 and s1>0","message":"Rates must be above zero."}],"steps":[{"id":"es","label":"Expected spot under parity","expr":"s0*(1+rd)/(1+rf)","format":"num4"},{"id":"chg","label":"Expected change in the euro","expr":"es/s0-1","format":"pct2"},{"id":"dir_","label":"Direction (1 = euro expected to rise, 0 = fall)","expr":"1 if chg>0 else 0","format":"num0"},{"id":"ru","label":"Unhedged return of the euro deposit in USD","expr":"(1+rf)*s1/s0-1","format":"pct2"},{"id":"ex","label":"Excess over the USD deposit","expr":"ru-rd","format":"pct2"}],"results":["es","chg","ru","ex"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"es":1.1060679611650486,"chg":0.01941747572815533,"dir_":1,"ru":0.06322580645161313,"ex":1.3225806451613129e-2}},"finder":{"finds":"The currency move that cancels an interest advantage","needs":"Spot, both rates, future spot"},"related":[{"slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage"},{"slug":"carry-trade-return","name":"Carry Trade Return and Break-Even"},{"slug":"international-fisher","name":"International Fisher Effect"}],"related_ids":["F434","F438","F437"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>E</mi><mo stretchy=\\"false\\">[</mo><msub><mi>S</mi><mn>1</mn></msub><mo stretchy=\\"false\\">]</mo><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub><mtext>\u2009</mtext><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>R</mi><mrow><mi>u</mi><mi>n</mi><mi>h</mi><mi>e</mi><mi>d</mi><mi>g</mi><mi>e</mi><mi>d</mi></mrow></msub><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><mo stretchy=\\"false\\">)</mo><mfrac><msub><mi>S</mi><mn>1</mn></msub><msub><mi>S</mi><mn>0</mn></msub></mfrac><mo>\u2212</mo><mn>1</mn></mrow><annotation encoding=\\"application/x-tex\\">E[S_{1}]=S_{0}\\\\,\\\\frac{1+r_{d}}{1+r_{f}},\\\\quad R_{unhedged}=(1+r_{f})\\\\frac{S_{1}}{S_{0}}-1</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>E</mi><mo stretchy=\\"false\\">[</mo><msub><mi>S</mi><mn>1</mn></msub><mo stretchy=\\"false\\">]</mo></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle E[S_{1}]</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msub><mi>S</mi><mn>0</mn></msub><mtext>\u2009</mtext><mfrac><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>d</mi></msub></mrow><mrow><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub></mrow></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =S_{0}\\\\,\\\\frac{1+r_{d}}{1+r_{f}}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mi>R</mi><mrow><mi>u</mi><mi>n</mi><mi>h</mi><mi>e</mi><mi>d</mi><mi>g</mi><mi>e</mi><mi>d</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle R_{unhedged}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>f</mi></msub><mo stretchy=\\"false\\">)</mo><mfrac><msub><mi>S</mi><mn>1</mn></msub><msub><mi>S</mi><mn>0</mn></msub></mfrac><mo>\u2212</mo><mn>1</mn></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =(1+r_{f})\\\\frac{S_{1}}{S_{0}}-1</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"hypothesis-test-two-means","name":"Two-Sample Z-Test for a Difference in Means"},"next":{"slug":"labor-market-rates","name":"Unemployment, Participation and Employment Rates"},"lesson":null,"total":522}')}}]);